    lotesExemplos: novos.filter(function (r) { return ex.test(normDesc_(r[2])); }).map(function (r) { return r[2] + ' saldo ' + r[9] + ' media ' + r[8] + ' -> ' + r[16]; }) };
  Logger.log(JSON.stringify(res, null, 1));
